import{_ as a,c as o,o as r,a3 as l}from"./chunks/framework.CoV49S2T.js";const u=JSON.parse('{"title":"使い方ガイド","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/usage.md","filePath":"ja/guide/usage.md","lastUpdated":1787284674000}'),e={name:"ja/guide/usage.md"};function n(i,t,s,d,g,h){return r(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="使い方ガイド" tabindex="-1">使い方ガイド <a class="header-anchor" href="#使い方ガイド" aria-label="Permalink to &quot;使い方ガイド&quot;">​</a></h1><h2 id="クリップボード履歴" tabindex="-1">クリップボード履歴 <a class="header-anchor" href="#クリップボード履歴" aria-label="Permalink to &quot;クリップボード履歴&quot;">​</a></h2><p>ClipboxAI は <strong>メニューバー</strong> から動作します。何かをコピーするたびに、履歴に追加されます。</p><ul><li>メニューバーのアイコンをクリックして履歴パネルを開きます。</li><li>項目にカーソルを合わせてアクションショートカットを押すか、クリックしてペーストボードへ再コピーします。</li><li>検索フィールドを使って、テキストで項目を探します。</li></ul><h2 id="ai-ツールウィンドウ" tabindex="-1">AI ツールウィンドウ <a class="header-anchor" href="#ai-ツールウィンドウ" aria-label="Permalink to &quot;AI ツールウィンドウ&quot;">​</a></h2><p><strong>AI ツール</strong> ウィンドウはアクションを実行する場所です。分割レイアウトになっています。</p><ul><li><strong>左側</strong> — ツールの一覧。次のグループに分かれています： <ul><li><strong>Built-in AI（内蔵 AI）</strong> — 要約、翻訳、その他の AI アクション。</li><li><strong>Built-in Local（内蔵ローカル）</strong> — オフラインツール（リンク抽出、集計、空白行削除）。</li><li><strong>Installed（インストール済み）</strong> — Marketplace から追加したアクション。<strong>ドラッグして並び順を変更</strong>できます。</li></ul></li><li><strong>右側</strong> — 2 つのペイン：<strong>original（元のクリップ）</strong> が一方、<strong>result（結果）</strong> がもう一方に表示されます。</li></ul><p>AI ツールには「cloud（クラウド）」のバッジが、ローカルツールには「device（端末）」のバッジが表示されるため、アクションがネットワークを使うかどうかは常にわかります。</p><h2 id="アクションの実行" tabindex="-1">アクションの実行 <a class="header-anchor" href="#アクションの実行" aria-label="Permalink to &quot;アクションの実行&quot;">​</a></h2><ol><li>左の一覧からツールを選択します（またはスマートな提案を受け入れます）。</li><li>現在のクリップが <strong>original</strong> ペインに表示されます。</li><li>結果が <strong>result</strong> ペインに生成されます。</li></ol><h3 id="自動実行-auto-run" tabindex="-1">自動実行（Auto-run） <a class="header-anchor" href="#自動実行-auto-run" aria-label="Permalink to &quot;自動実行（Auto-run）&quot;">​</a></h3><p>ウィンドウのフッターにある <strong>Auto-run on output（出力時の自動実行）</strong> をオンにします。有効にすると、コピーした瞬間に選択したツールが自動的に実行され、手動でクリックする必要はありません。ローカルツールはペーストボードを上書きすることはないため、自動実行は安全です。</p><h2 id="内蔵のローカルツール" tabindex="-1">内蔵のローカルツール <a class="header-anchor" href="#内蔵のローカルツール" aria-label="Permalink to &quot;内蔵のローカルツール&quot;">​</a></h2><p>これらは Mac 上で完全にオフラインで動作します。</p><ul><li><strong>Extract Links（リンク抽出）</strong> — テキスト内のすべての URL を返します。</li><li><strong>Count Stats（集計）</strong> — 単語数 / 文字数 / 行数 / 文の数をカウントします。</li><li><strong>Collapse Blank Lines（空白行削除）</strong> — 貼り付けたテキストから空行を削除します。</li></ul><h2 id="クラウド-ai-の設定" tabindex="-1">クラウド AI の設定 <a class="header-anchor" href="#クラウド-ai-の設定" aria-label="Permalink to &quot;クラウド AI の設定&quot;">​</a></h2><p>AI アクションを使うには、<strong>設定 → AI</strong> でプロバイダーに接続します。</p><ol><li>プロバイダーを選択します — <strong>DeepSeek</strong>、<strong>MiniMax</strong>、<strong>Zhipu GLM</strong>、<strong>Kimi (Moonshot)</strong>、<strong>Mistral</strong>、<strong>Ollama</strong>（ローカル）、またはその他の OpenAI 互換サービス。</li><li><strong>API key</strong> を貼り付けます。これは <strong>Keychain</strong> に保存され、平文でディスクに書き込まれることはありません。</li><li>モデルを選択します。</li><li>クラウド AI は既定でオフです。有効にした場合、クリップが送信されるのは自分で設定したプロバイダーだけです。</li></ol><p>キーが設定されていない場合、AI ツールウィンドウ内に設定バナーで通知されます。</p><h2 id="マーケットプレイス" tabindex="-1">マーケットプレイス <a class="header-anchor" href="#マーケットプレイス" aria-label="Permalink to &quot;マーケットプレイス&quot;">​</a></h2><ol><li>AI ツールウィンドウから <strong>Marketplace</strong> を開きます（またはサイトの <a href="/ja/marketplace/">Marketplace</a> ページ）。</li><li>アクションの <strong>Install</strong> をクリックします。これによりディープリンク <code>clipboxai://install?action=&lt;id&gt;</code> を通じてアプリが開き、アクションが <strong>Installed（インストール済み）</strong> 一覧に追加されます。</li></ol><h2 id="キーボードショートカット" tabindex="-1">キーボードショートカット <a class="header-anchor" href="#キーボードショートカット" aria-label="Permalink to &quot;キーボードショートカット&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ショートカット</th><th>アクション</th></tr></thead><tbody><tr><td><code>Cmd+Shift+V</code></td><td>クリップボード履歴を開く</td></tr><tr><td><code>Cmd+,</code></td><td>設定を開く</td></tr><tr><td><code>Cmd+W</code></td><td>ウィンドウを閉じる</td></tr><tr><td><code>Cmd+Q</code></td><td>アプリケーションを終了</td></tr></tbody></table><blockquote><p>正確なショートカットはビルドによって異なる場合があります。アプリ内の <strong>設定 → Shortcuts</strong> をご確認ください。</p></blockquote><h2 id="設定" tabindex="-1">設定 <a class="header-anchor" href="#設定" aria-label="Permalink to &quot;設定&quot;">​</a></h2><p><strong>ClipboxAI → 設定</strong>（または <code>Cmd+,</code>）を開きます。</p><ul><li><strong>General（一般）</strong>: 言語、ログイン時の起動、外観テーマ。</li><li><strong>AI</strong>: クラウドプロバイダー、モデル、API key（Keychain）。</li><li><strong>Actions（アクション）</strong>: 自動実行の切り替え、除外アプリ、ツールの順序。</li><li><strong>Privacy（プライバシー）</strong>: クラウド AI のオプトイン、除外アプリ、履歴の管理。</li><li><strong>Marketplace（マーケットプレイス）</strong>: インストール済みアクションの閲覧と管理。</li></ul>',27)])])}const p=a(e,[["render",n]]);export{u as __pageData,p as default};
